use nihav_core::io::byteio::{ByteReader,MemoryReader};
use nihav_core::codecs::*;
use nihav_codec_support::codecs::imaadpcm::*;

#[derive(Default)]
struct FrameContext {
    pframe:     Vec<u8>,
    width:      usize,
    height:     usize,
    fill:       [u8; 8],
    op_run:     usize,
    op_val:     u8,
    subop_run:  usize,
    subop_val:  u8,
    sub2op_run: usize,
    sub2op_val: u8,
}

impl FrameContext {
    fn decode_block2(&mut self, br: &mut ByteReader, dst: &mut [u8], xpos: usize, ypos: usize) -> DecoderResult<()> {
        let op = if self.sub2op_run > 0 {
                self.sub2op_run -= 1;
                self.sub2op_val
            } else {
                let opcode = br.read_byte()?;
                if opcode != 0xF3 {
                    opcode
                } else {
                    self.sub2op_run = usize::from(br.read_byte()?) + 3;
                    self.sub2op_val = br.read_byte()?;
                    validate!(self.sub2op_val != 0xF3);
                    self.sub2op_val
                }
            };
        match op {
            0x00..=0xE0 => {
                let (mv_x, mv_y) = MVS[usize::from(op)];
                let src_x = (xpos as isize) + isize::from(mv_x);
                let src_y = (ypos as isize) + isize::from(mv_y);
                let src_pos = src_x + src_y * (self.width as isize);
                validate!(src_pos >= 0);
                let src_pos = src_pos as usize;
                validate!(src_pos + 2 + self.width <= self.pframe.len());
                for (dline, sline) in dst.chunks_exact_mut(self.width).skip(ypos & 7)
                        .zip(self.pframe[src_pos..].chunks(self.width)).take(2) {
                    dline[xpos..][..2].copy_from_slice(&sline[..2]);
                }
            },
            0xF3 => unreachable!(),
            0xF4 => {}, // skip
            0xF6..=0xFD => {
                let clr = self.fill[usize::from(op - 0xF6)];
                for dline in dst.chunks_exact_mut(self.width).skip(ypos & 7).take(2) {
                    for el in dline[xpos..][..2].iter_mut() {
                        *el = clr;
                    }
                }
            },
            0xFE => {
                let clr = br.read_byte()?;
                for dline in dst.chunks_exact_mut(self.width).skip(ypos & 7).take(2) {
                    for el in dline[xpos..][..2].iter_mut() {
                        *el = clr;
                    }
                }
            },
            0xFF => {
                for dline in dst.chunks_exact_mut(self.width).skip(ypos & 7).take(2) {
                    br.read_buf(&mut dline[xpos..][..2])?;
                }
            },
            _ => {
                println!("Unknown block2 opcode {op:02X}");
                return Err(DecoderError::InvalidData);
            },
        }
        Ok(())
    }
    fn decode_block4(&mut self, br: &mut ByteReader, dst: &mut [u8], xpos: usize, ypos: usize, split: bool) -> DecoderResult<()> {
        let op = if split {
                0xFF
            } else if self.subop_run > 0 {
                self.subop_run -= 1;
                self.subop_val
            } else {
                let opcode = br.read_byte()?;
                if opcode != 0xF3 {
                    opcode
                } else {
                    self.subop_run = usize::from(br.read_byte()?) + 3;
                    self.subop_val = br.read_byte()?;
                    validate!(self.subop_val != 0xF3);
                    self.subop_val
                }
            };
        let mut clrs = [0; 2];
        match op {
            0x00..=0xE0 => {
                let (mv_x, mv_y) = MVS[usize::from(op)];
                let src_x = (xpos as isize) + isize::from(mv_x);
                let src_y = (ypos as isize) + isize::from(mv_y);
                let src_pos = src_x + src_y * (self.width as isize);
                validate!(src_pos >= 0);
                let src_pos = src_pos as usize;
                validate!(src_pos + 4 + 3 * self.width <= self.pframe.len());
                for (dline, sline) in dst.chunks_exact_mut(self.width).skip(ypos & 4)
                        .zip(self.pframe[src_pos..].chunks(self.width)).take(4) {
                    dline[xpos..][..4].copy_from_slice(&sline[..4]);
                }
            },
            0xF3 => unreachable!(),
            0xF4 => {}, // skip
            0xF5 => {
                let mut pattern = BLOCK4_PATTERNS[usize::from(br.read_byte()?)] as usize;
                br.read_buf(&mut clrs)?;
                for dline in dst.chunks_exact_mut(self.width).skip(ypos & 4).take(4) {
                    for el in dline[xpos..][..4].iter_mut() {
                        *el = clrs[pattern & 1];
                        pattern >>= 1;
                    }
                }
            },
            0xF6..=0xFD => {
                let clr = self.fill[usize::from(op - 0xF6)];
                for dline in dst.chunks_exact_mut(self.width).skip(ypos & 4).take(4) {
                    for el in dline[xpos..][..4].iter_mut() {
                        *el = clr;
                    }
                }
            },
            0xFE => {
                let clr = br.read_byte()?;
                for dline in dst.chunks_exact_mut(self.width).skip(ypos & 4).take(4) {
                    for el in dline[xpos..][..4].iter_mut() {
                        *el = clr;
                    }
                }
            },
            0xFF => {
                self.decode_block2(br, dst, xpos,     ypos)?;
                self.decode_block2(br, dst, xpos + 2, ypos)?;
                self.decode_block2(br, dst, xpos + 2, ypos + 2)?;
                self.decode_block2(br, dst, xpos,     ypos + 2)?;
            },
            _ => {
                println!("Unknown block4 opcode {op:02X}");
                return Err(DecoderError::InvalidData);
            },
        }
        Ok(())
    }
    fn unpack_frame(&mut self, br: &mut ByteReader, dst: &mut [u8]) -> DecoderResult<()> {
        self.op_run = 0;
        self.op_val = 0;
        self.subop_run = 0;
        self.sub2op_run = 0;
        let mut clrs = [0; 2];
        for (tile_y, strip) in dst.chunks_exact_mut(self.width * 8).enumerate() {
            for tile_x in 0..(self.width / 8) {
                let op = if self.op_run == 0 {
                        let opcode = br.read_byte()?;
                        if opcode != 0xF3 {
                            opcode
                        } else {
                            self.op_run = usize::from(br.read_byte()?) + 3;
                            self.op_val = br.read_byte()?;
                            validate!(self.op_val != 0xF3);
                            self.op_val
                        }
                    } else {
                        self.op_run -= 1;
                        self.op_val
                    };
                match op {
                    0x00..=0xE0 => {
                        let (mv_x, mv_y) = MVS[usize::from(op)];
                        let src_x = (tile_x as isize) * 8 + isize::from(mv_x);
                        let src_y = (tile_y as isize) * 8 + isize::from(mv_y);
                        let src_pos = src_x + src_y * (self.width as isize);
                        validate!(src_pos >= 0);
                        let src_pos = src_pos as usize;
                        validate!(src_pos + 8 + 7 * self.width <= self.pframe.len());
                        for (dline, sline) in strip.chunks_exact_mut(self.width)
                                .zip(self.pframe[src_pos..].chunks(self.width)) {
                            dline[tile_x * 8..][..8].copy_from_slice(&sline[..8]);
                        }
                    },
                    0xE1..=0xF0 => {
                        let cbp = (op - 1) & 0xF;
                        self.decode_block4(br, strip, tile_x * 8,     tile_y * 8,     (cbp & 1) != 0)?;
                        self.decode_block4(br, strip, tile_x * 8 + 4, tile_y * 8,     (cbp & 2) != 0)?;
                        self.decode_block4(br, strip, tile_x * 8 + 4, tile_y * 8 + 4, (cbp & 4) != 0)?;
                        self.decode_block4(br, strip, tile_x * 8,     tile_y * 8 + 4, (cbp & 8) != 0)?;
                    },
                    0xF3 => unreachable!(),
                    0xF4 => {}, // skip
                    0xF5 => {
                        let mut pattern = PATTERNS[usize::from(br.read_byte()?)];
                        br.read_buf(&mut clrs)?;
                        for dline in strip.chunks_exact_mut(self.width) {
                            for el in dline[tile_x * 8..][..8].iter_mut() {
                                *el = clrs[(pattern & 1) as usize];
                                pattern >>= 1;
                            }
                        }
                    },
                    0xF6..=0xFD => {
                        let clr = self.fill[usize::from(op - 0xF6)];
                        for dline in strip.chunks_exact_mut(self.width) {
                            for el in dline[tile_x * 8..][..8].iter_mut() {
                                *el = clr;
                            }
                        }
                    },
                    0xFE => {
                        let clr = br.read_byte()?;
                        for dline in strip.chunks_exact_mut(self.width) {
                            for el in dline[tile_x * 8..][..8].iter_mut() {
                                *el = clr;
                            }
                        }
                    },
                    0xFF => {
                        self.decode_block4(br, strip, tile_x * 8,     tile_y * 8,     false)?;
                        self.decode_block4(br, strip, tile_x * 8 + 4, tile_y * 8,     false)?;
                        self.decode_block4(br, strip, tile_x * 8 + 4, tile_y * 8 + 4, false)?;
                        self.decode_block4(br, strip, tile_x * 8,     tile_y * 8 + 4, false)?;
                    },
                    _ => {
                        println!("Unknown opcode {op:02X}");
                        return Err(DecoderError::InvalidData);
                    },
                }
            }
        }
        Ok(())
    }
}

#[derive(Default)]
struct FrameDecoder {
    frame:      Vec<u8>,
    fctx:       FrameContext,
    vtype:      u8,
}

impl FrameDecoder {
    fn set_dimensions(&mut self, w: usize, h: usize) {
        self.fctx.width  = w;
        self.fctx.height = h;
        self.frame  = vec![0; self.fctx.width * self.fctx.height];
        self.fctx.pframe = vec![0; self.fctx.width * self.fctx.height];
    }
    fn load_raw_frame(&mut self, br: &mut ByteReader) -> DecoderResult<()> {
        if self.fctx.width == 160 {
            br.read_buf(&mut self.frame)?;
        } else {
            for dline in self.frame.chunks_exact_mut(self.fctx.width * 2) {
                let (line0, line1) = dline.split_at_mut(self.fctx.width);
                for pair in line0.chunks_exact_mut(2) {
                    pair[0] = br.read_byte()?;
                    pair[1] = pair[0];
                }
                line1.copy_from_slice(line0);
            }
        }
        self.fctx.pframe.copy_from_slice(&self.frame);
        Ok(())
    }
    fn flush(&mut self) {
        for el in self.frame.iter_mut() {
            *el = 0;
        }
        for el in self.fctx.pframe.iter_mut() {
            *el = 0;
        }
    }
    fn swap_bufs(&mut self) {
        std::mem::swap(&mut self.frame, &mut self.fctx.pframe);
    }
    fn store_pal_frame(&self, buf: &mut NAVideoBuffer<u8>, pal: &[u8; 768]) {
        let stride = buf.get_stride(0);
        let pal_off = buf.get_offset(1);
        let data = buf.get_data_mut().unwrap();

        for (dline, sline) in data.chunks_mut(stride).zip(self.frame.chunks_exact(self.fctx.width)) {
            dline[..self.fctx.width].copy_from_slice(sline);
        }
        data[pal_off..][..768].copy_from_slice(pal);
    }
    fn store_rgb16_frame(&self, buf: &mut NAVideoBuffer<u16>) {
        let dstride = buf.get_stride(0);
        let data = buf.get_data_mut().unwrap();
        let sstride = self.fctx.width;
        let (src_y, src_c) = self.frame.split_at(sstride * (self.fctx.height * 2 / 3));

        let tab = if self.vtype == 5 { &RGB_TAB[0] } else { &RGB_TAB[1] };
        for (dlines, (ylines, cline)) in data.chunks_mut(dstride * 2)
                .zip(src_y.chunks_exact(sstride * 2).zip(src_c.chunks_exact(sstride))) {
            let (dline0, dline1) = dlines.split_at_mut(dstride);
            let (yline0, yline1) = ylines.split_at(sstride);
            let (uline, vline) = cline.split_at(sstride / 2);
            for ((dpair, ypair), (&u, &v)) in dline0.chunks_exact_mut(2).zip(yline0.chunks_exact(2))
                    .zip(uline.iter().zip(vline.iter())) {
                dpair[0] = yuv2rgb(ypair[0], u, v, tab);
                dpair[1] = yuv2rgb(ypair[1], u, v, tab);
            }
            for ((dpair, ypair), (&u, &v)) in dline1.chunks_exact_mut(2).zip(yline1.chunks_exact(2))
                    .zip(uline.iter().zip(vline.iter())) {
                dpair[0] = yuv2rgb(ypair[0], u, v, tab);
                dpair[1] = yuv2rgb(ypair[1], u, v, tab);
            }
        }
    }
}

fn yuv2rgb(y: u8, u: u8, v: u8, tab: &[u16; 32768]) -> u16 {
    let chroma = (usize::from(u) + usize::from(v)) << 7;
    tab[(usize::from(y) + chroma).min(tab.len() - 1)]
}

struct TealVideoDecoder {
    info:       NACodecInfoRef,
    pal:        [u8; 768],
    fdec:       FrameDecoder,
    is_16bpp:   bool,
}

impl TealVideoDecoder {
    fn new() -> Self {
        Self {
            info:       NACodecInfo::new_dummy(),
            pal:        [0; 768],
            fdec:       FrameDecoder::default(),
            is_16bpp:   false,
        }
    }
}

impl NADecoder for TealVideoDecoder {
    fn init(&mut self, _supp: &mut NADecoderSupport, info: NACodecInfoRef) -> DecoderResult<()> {
        if let NACodecTypeInfo::Video(vinfo) = info.get_properties() {
            let w = vinfo.get_width();
            let h = vinfo.get_height();
            validate!(((w | h) & 7) == 0);
            if let Some(edata) = info.get_extradata() {
                validate!(!edata.is_empty());
                self.fdec.vtype = edata[0];
            }
            self.is_16bpp = self.fdec.vtype >= 4;
            let fmt = if !self.is_16bpp {
                    self.fdec.set_dimensions(w, h);
                    PAL8_FORMAT
                } else {
                    self.fdec.set_dimensions(w, h * 3 / 2);
                    RGB565_FORMAT
                };
            let myinfo = NACodecTypeInfo::Video(NAVideoInfo::new(w, h, false, fmt));
            self.info = NACodecInfo::new_ref(info.get_name(), myinfo, info.get_extradata()).into_ref();
            Ok(())
        } else {
            Err(DecoderError::InvalidData)
        }
    }
    fn decode(&mut self, _supp: &mut NADecoderSupport, pkt: &NAPacket) -> DecoderResult<NAFrameRef> {
        let src = pkt.get_buffer();
        let mut mr = MemoryReader::new_read(&src);
        let mut br = ByteReader::new(&mut mr);

        let frm_type = br.read_u16be()?;
        let _is_last = (br.read_u16be()? & 1) == 0;

        match frm_type {
            1 => {
                let start_clr = br.read_u16be()? as usize;
                let num_clrs  = br.read_u16be()? as usize;
                validate!(num_clrs > 0 && start_clr + num_clrs <= 256);
                let hdr_size  = br.read_u32be()? as usize;
                validate!(hdr_size == 0 || hdr_size == 16);
                let img_off = br.read_u32be()? as usize;
                validate!(img_off >= 16);
                if hdr_size == 16 && img_off >= 16 + num_clrs * 3 {
                    br.read_buf(&mut self.pal[start_clr * 3..][..num_clrs * 3])?;
                    br.read_skip(img_off - 16 - num_clrs * 3)?;
                } else {
                    br.read_skip(img_off - 16)?;
                }
                self.fdec.load_raw_frame(&mut br)?;
            },
            2 => {
                self.fdec.swap_bufs();
                br.read_skip(8)?;
                br.read_buf(&mut self.fdec.fctx.fill)?;
                let hdr_size = br.read_u32be()? as usize;
                validate!(hdr_size == 24);
                self.fdec.fctx.unpack_frame(&mut br, &mut self.fdec.frame)?;
            },
            _ => {
                let mut frm = NAFrame::new_from_pkt(pkt, self.info.clone(), NABufferType::None);
                frm.set_keyframe(false);
                frm.set_frame_type(FrameType::Skip);
                return Ok(frm.into_ref());
            },
        }

        let vinfo = self.info.get_properties().get_video_info().unwrap();
        let bufinfo = alloc_video_buffer(vinfo, 3)?;

        if let Some(mut buf) = bufinfo.get_vbuf() {
            self.fdec.store_pal_frame(&mut buf, &self.pal);
        } else if let Some(mut buf) = bufinfo.get_vbuf16() {
            self.fdec.store_rgb16_frame(&mut buf);
        } else { unreachable!(); }

        let is_intra = frm_type == 1;
        let mut frm = NAFrame::new_from_pkt(pkt, self.info.clone(), bufinfo);
        frm.set_keyframe(is_intra);
        frm.set_frame_type(if is_intra { FrameType::I } else { FrameType::P });
        Ok(frm.into_ref())
    }
    fn flush(&mut self) {
        for el in self.pal.iter_mut() {
            *el = 0;
        }
        self.fdec.flush();
    }
}

impl NAOptionHandler for TealVideoDecoder {
    fn get_supported_options(&self) -> &[NAOptionDefinition] { &[] }
    fn set_options(&mut self, _options: &[NAOption]) { }
    fn query_option_value(&self, _name: &str) -> Option<NAValue> { None }
}

pub fn get_decoder_video() -> Box<dyn NADecoder + Send> {
    Box::new(TealVideoDecoder::new())
}

struct TealAudioDecoder {
    ainfo:      NAAudioInfo,
    chmap:      NAChannelMap,
    ch_state:   IMAState,
}

impl TealAudioDecoder {
    fn new() -> Self {
        Self {
            ainfo:      NAAudioInfo::new(0, 1, SND_S16P_FORMAT, 0),
            chmap:      NAChannelMap::new(),
            ch_state:   IMAState::new(),
        }
    }
}

impl NADecoder for TealAudioDecoder {
    fn init(&mut self, _supp: &mut NADecoderSupport, info: NACodecInfoRef) -> DecoderResult<()> {
        if let NACodecTypeInfo::Audio(ainfo) = info.get_properties() {
            let channels = ainfo.get_channels();
            validate!(channels == 1);
            self.ainfo = NAAudioInfo::new(ainfo.get_sample_rate(), channels, SND_S16_FORMAT, 2);
            self.chmap = NAChannelMap::from_str("C").unwrap();
            Ok(())
        } else {
            Err(DecoderError::InvalidData)
        }
    }
    fn decode(&mut self, _supp: &mut NADecoderSupport, pkt: &NAPacket) -> DecoderResult<NAFrameRef> {
        let info = pkt.get_stream().get_info();
        if let NACodecTypeInfo::Audio(_) = info.get_properties() {
            let pktbuf = pkt.get_buffer();
            let channels = self.ainfo.get_channels();
            let nsamples = pktbuf.len() * 2 / usize::from(channels);
            let abuf = alloc_audio_buffer(self.ainfo, nsamples, self.chmap.clone())?;
            let mut adata = abuf.get_abuf_i16().unwrap();
            let dst = adata.get_data_mut().unwrap();
            for (dpair, &src) in dst.chunks_exact_mut(2).zip(pktbuf.iter()) {
                dpair[0] =  self.ch_state.expand_sample(src >> 4);
                dpair[1] = !self.ch_state.expand_sample(src & 0xF);
            }

            let mut frm = NAFrame::new_from_pkt(pkt, info, abuf);
            frm.set_duration(Some(nsamples as u64));
            frm.set_keyframe(false);
            Ok(frm.into_ref())
        } else {
            Err(DecoderError::InvalidData)
        }
    }
    fn flush(&mut self) {
        self.ch_state.reset(0, 0);
    }
}

impl NAOptionHandler for TealAudioDecoder {
    fn get_supported_options(&self) -> &[NAOptionDefinition] { &[] }
    fn set_options(&mut self, _options: &[NAOption]) { }
    fn query_option_value(&self, _name: &str) -> Option<NAValue> { None }
}

pub fn get_decoder_audio() -> Box<dyn NADecoder + Send> {
    Box::new(TealAudioDecoder::new())
}

#[cfg(test)]
mod test {
    use nihav_core::codecs::RegisteredDecoders;
    use nihav_core::demuxers::RegisteredDemuxers;
    use nihav_codec_support::test::dec_video::*;
    use crate::*;
    use nihav_commonfmt::generic_register_all_demuxers;
    #[test]
    fn test_teal_video_pal() {
        let mut dmx_reg = RegisteredDemuxers::new();
        misc_register_all_demuxers(&mut dmx_reg);
        generic_register_all_demuxers(&mut dmx_reg);
        let mut dec_reg = RegisteredDecoders::new();
        misc_register_all_decoders(&mut dec_reg);

        // sample bundled with TealMovie player
        test_decoding("tealmov", "teal-video", "assets/Misc/ASTRONUT.PDB", Some(3), &dmx_reg,
                     &dec_reg, ExpectedTestResult::MD5Frames(vec![
                            [0x92d83537, 0xf0895ce2, 0xa818ad7c, 0x44e8206d],
                            [0xfdbe16da, 0xf39d4555, 0x7d30c54a, 0x6607aba5],
                            [0xe24fbe39, 0x98173b37, 0x19306446, 0xb3a3f0f8],
                            [0xa227d699, 0x8bdcd899, 0xebe23888, 0xd7704b6a]]));
    }
    #[test]
    fn test_teal_video_v4() {
        let mut dmx_reg = RegisteredDemuxers::new();
        misc_register_all_demuxers(&mut dmx_reg);
        generic_register_all_demuxers(&mut dmx_reg);
        let mut dec_reg = RegisteredDecoders::new();
        misc_register_all_decoders(&mut dec_reg);

        // sample from TealMovie site
        test_decoding("tealmov", "teal-video", "assets/Misc/extra16b.pdb", Some(6), &dmx_reg,
                     &dec_reg, ExpectedTestResult::MD5Frames(vec![
                            [0xbf235f22, 0xdf3e004e, 0xde210419, 0x78c24f2e],
                            [0xbf235f22, 0xdf3e004e, 0xde210419, 0x78c24f2e],
                            [0x0a17db42, 0xcfef5f15, 0xf01fc9b6, 0x0765bc04],
                            [0xf70a601f, 0xb20ccf27, 0x3d8dd6ac, 0x3770104f],
                            [0xbda595ed, 0xe5dbe09e, 0xf8e50d2b, 0x8c60393c],
                            [0x455b7bfb, 0x77cf9bef, 0xca73b538, 0xce66328f],
                            [0x94538882, 0xe22290c7, 0x8d12586e, 0xb511d947]]));
    }
    #[test]
    fn test_teal_video_v5() {
        let mut dmx_reg = RegisteredDemuxers::new();
        misc_register_all_demuxers(&mut dmx_reg);
        generic_register_all_demuxers(&mut dmx_reg);
        let mut dec_reg = RegisteredDecoders::new();
        misc_register_all_decoders(&mut dec_reg);

        // sample from TealMovie site
        test_decoding("tealmov", "teal-video", "assets/Misc/MISSTEEN.PDB", Some(3), &dmx_reg,
                     &dec_reg, ExpectedTestResult::MD5Frames(vec![
                            [0x387abe90, 0xa15a3e71, 0xcf227ff6, 0x3aa1a2d9],
                            [0xc66701f8, 0x93017e24, 0x7e123981, 0x7c554d26],
                            [0x3612b1fd, 0xdd6866ec, 0xa2ebb689, 0x70095c88],
                            [0x9992426d, 0x24ebc37b, 0xb3665ce9, 0xf2602480]]));
    }
    #[test]
    fn test_teal_audio() {
        let mut dmx_reg = RegisteredDemuxers::new();
        misc_register_all_demuxers(&mut dmx_reg);
        generic_register_all_demuxers(&mut dmx_reg);
        let mut dec_reg = RegisteredDecoders::new();
        misc_register_all_decoders(&mut dec_reg);

        // sample bundled with TealMovie player
        test_decoding("tealmov", "teal-audio", "assets/Misc/ASTRONUT.PDB", None, &dmx_reg,
                     &dec_reg, ExpectedTestResult::MD5([0xb0a39a89, 0x8c6c784f, 0x62e9f461, 0x5a66ce97]));
    }
}

